:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --success: #4ecca3;
  --warning: #f0a500;
  --danger: #e94560;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 0.5px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

label {
  font-weight: 600;
  font-size: 1rem;
}

input[type="range"] {
  width: 100%;
  height: 8px;
  appearance: none;
  background: var(--accent);
  border-radius: 4px;
  outline: none;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--highlight);
  cursor: pointer;
  transition: transform 0.15s;
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--highlight);
  cursor: pointer;
  border: none;
}

input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:focus-visible::-webkit-slider-thumb {
  transform: scale(1.15);
}

input[type="range"]:focus-visible {
  outline: 2px solid var(--highlight);
  outline-offset: 4px;
}

.help {
  font-size: 0.875rem;
  color: var(--muted);
}

.toggles {
  border: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.toggles legend {
  font-weight: 600;
  margin-bottom: 4px;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  padding: 8px 12px;
  border-radius: 8px;
  transition: background 0.15s;
}

.toggle:hover {
  background: var(--accent);
}

.toggle input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--highlight);
  cursor: pointer;
}

.toggle input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--highlight);
  outline-offset: 2px;
}

.btn {
  background: var(--highlight);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 14px 24px;
  font-size: 1.125rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: var(--font);
}

.btn:hover {
  background: #c73650;
}

.btn:active {
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}

.output-box {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 16px;
  min-height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  word-break: break-all;
  text-align: center;
}

.password {
  font-family: 'Courier New', monospace;
  font-size: 1.25rem;
  letter-spacing: 1px;
  color: var(--text);
}

.strength {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 1rem;
}

.strength-label {
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 6px;
  background: var(--accent);
  color: var(--text);
}

.strength-label.weak { background: var(--danger); color: #fff; }
.strength-label.fair { background: var(--warning); color: #1a1a2e; }
.strength-label.good { background: var(--success); color: #1a1a2e; }
.strength-label.strong { background: #2ecc71; color: #1a1a2e; }

.strength-bar {
  flex: 1;
  height: 8px;
  background: var(--accent);
  border-radius: 4px;
  overflow: hidden;
  min-width: 80px;
}

.strength-bar::after {
  content: '';
  display: block;
  height: 100%;
  width: var(--strength-width, 0%);
  background: var(--strength-color, var(--muted));
  border-radius: 4px;
  transition: width 0.3s, background 0.3s;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .password {
    font-size: 1rem;
  }
}

const lengthInput = document.getElementById('length');
const lengthValue = document.getElementById('length-value');
const uppercaseToggle = document.getElementById('uppercase');
const numbersToggle = document.getElementById('numbers');
const symbolsToggle = document.getElementById('symbols');
const generateBtn = document.getElementById('generate');
const passwordEl = document.getElementById('password');
const strengthLabel = document.getElementById('strength-label');
const strengthBar = document.getElementById('strength-bar');

const LOWERCASE = 'abcdefghijklmnopqrstuvwxyz';
const UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const NUMBERS = '0123456789';
const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

function getSelectedSets() {
  const sets = [LOWERCASE];
  if (uppercaseToggle.checked) sets.push(UPPERCASE);
  if (numbersToggle.checked) sets.push(NUMBERS);
  if (symbolsToggle.checked) sets.push(SYMBOLS);
  return sets;
}

function generatePassword(length) {
  const sets = getSelectedSets();
  const allChars = sets.join('');
  let password = '';
  for (let i = 0; i < length; i++) {
    password += allChars[Math.floor(Math.random() * allChars.length)];
  }
  return password;
}

function evaluateStrength(password) {
  const length = password.length;
  const hasUpper = /[A-Z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  const hasSymbol = /[^A-Za-z0-9]/.test(password);
  const variety = 1 + (hasUpper ? 1 : 0) + (hasNumber ? 1 : 0) + (hasSymbol ? 1 : 0);
  const score = length * variety;

  if (score < 30) return { label: 'Weak', class: 'weak', width: '25%', color: 'var(--danger)' };
  if (score < 60) return { label: 'Fair', class: 'fair', width: '50%', color: 'var(--warning)' };
  if (score < 100) return { label: 'Good', class: 'good', width: '75%', color: 'var(--success)' };
  return { label: 'Strong', class: 'strong', width: '100%', color: '#2ecc71' };
}

function updateStrength(password) {
  const result = evaluateStrength(password);
  strengthLabel.textContent = result.label;
  strengthLabel.className = 'strength-label ' + result.class;
  strengthBar.style.setProperty('--strength-width', result.width);
  strengthBar.style.setProperty('--strength-color', result.color);
}

function updateLength() {
  const val = Math.min(32, Math.max(8, parseInt(lengthInput.value, 10) || 16));
  lengthInput.value = val;
  lengthValue.textContent = val;
}

function handleGenerate() {
  updateLength();
  const length = parseInt(lengthInput.value, 10);
  const password = generatePassword(length);
  passwordEl.textContent = password;
  updateStrength(password);
}

lengthInput.addEventListener('input', updateLength);
generateBtn.addEventListener('click', handleGenerate);

// Ensure at least one set is always active
[uppercaseToggle, numbersToggle, symbolsToggle].forEach(toggle => {
  toggle.addEventListener('change', () => {
    if (!uppercaseToggle.checked && !numbersToggle.checked && !symbolsToggle.checked) {
      toggle.checked = true;
    }
  });
});

// Initialize strength display
updateStrength('');
